import * as cloud from './firebase.js';
import { getCachedData, putCachedData } from './local-db.js';
import { initPWA, installApp, applyUpdate, isStandalone } from './pwa.js';
import { SYMPTOMS, evaluateSymptoms } from './triage.js';
import { validateModelURL, loadPlantModel, classifyPlant } from './classifier.js';
import { reportHTML, downloadReport } from './report.js';
import { initTheme, renderThemeSwitch } from './theme.js';
import { initExperience, finishSplash, showLoading, updateLoading, hideLoading, loaderHTML } from './experience.js';

initTheme();
initExperience();
document.documentElement.dataset.ecoplantStarted = "true";

const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid = () => globalThis.crypto?.randomUUID?.() || 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const bytes=new Uint8Array(1);globalThis.crypto.getRandomValues(bytes);const r=bytes[0]%16;return (c==='x'?r:(r&3)|8).toString(16);});
const paths = {
 leaf:'M20 4c-9-1-16 2-16 9a7 7 0 0 0 7 7c7 0 10-7 9-16ZM4 20 15 9M9 15v-5m0 5h5',
 home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
 plants:'M12 21v-9M12 16C4 17 2 12 3 6c7 0 10 3 9 10ZM12 12c-1-6 3-10 9-10 1 6-2 11-9 10Z',
 clock:'M21 12a9 9 0 1 1-9-9 9 9 0 0 1 9 9ZM12 7v5l3 2',
 user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',
 camera:'M8 5 9 3h6l1 2h4a1 1 0 0 1 1 1v13H3V6a1 1 0 0 1 1-1ZM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
 plus:'M12 5v14M5 12h14', right:'m9 5 7 7-7 7', back:'m15 5-7 7 7 7',
 search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-2 5 6 6',
 download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
 sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',
 drop:'M12 2C10 6 5 11 5 15a7 7 0 0 0 14 0c0-4-5-9-7-13Z',
 check:'m5 12 4 4L19 6', info:'M12 11v6m0-10v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
 pin:'M18 9c0 5-6 12-6 12S6 14 6 9a6 6 0 0 1 12 0Zm-4 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',
 edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14ZM3 22h18',
 trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',
 logout:'M10 4H4v16h6M8 12h13m-5-5 5 5-5 5',
 lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4ZM12 14v4',
 eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
 gallery:'M3 3h18v18H3ZM3 17l5-5 4 4 4-6 5 7M8 7v.1',
 close:'m6 6 12 12M6 18 18 6', help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4m0 4v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
 spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z', mail:'M3 5h18v14H3Zm0 0 9 8 9-8',
 switch:'M4 8h15m-4-4 4 4-4 4M20 16H5m4-4-4 4 4 4', bell:'M4 17h16l-2-3V8a6 6 0 0 0-12 0v6Zm6 4h4',
 file:'M14 2H5v20h14V7ZM14 2v6h5M8 12h8M8 16h8', arrow:'M4 12h16m-6-6 6 6-6 6'
};
function icon(name, cls=''){ return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.leaf}"/></svg>`; }
const state = {user:null,guest:false,profile:{},plants:[],analyses:[],source:'cloud',dataError:'',scanPhoto:'',scanSymptoms:[],scanNotes:'',scanPlantId:'',scanMethod:'',draft:null,plantPhoto:null,profilePhoto:null,model:null};
let unsubscribeData=()=>{}, cameraStream=null, cameraFacing='environment', toastTimer, authResolved=false, modelLoading=false;
let lastRenderedRoute='';
const pendingForms=new Set();
const blankData = () => ({profile:{},plants:[],analyses:[]});
const date = value => { const d=new Date(value||Date.now()); return isNaN(d)?'Data indisponível':new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Sao_Paulo'}).format(d); };
const name = () => state.profile.displayName || state.profile.name || state.user?.displayName || 'Seu jardim';
const firstName = () => name().split(' ')[0];
const currentRoute = () => (location.hash || (state.user?'#home':'#login')).slice(1);
const routePath = () => currentRoute().split('?')[0];
const routeParams = () => new URLSearchParams(currentRoute().split('?')[1] || '');
const findPlant = id => state.plants.find(p => p.id===id);
const sortedAnalyses = () => [...state.analyses].sort((a,b)=>Number(b.date||b.createdAt)-Number(a.date||a.createdAt));
const latest = id => sortedAnalyses().find(a=>a.plantId===id);
const photoSafe = value => typeof value==='string' && /^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value) ? value : '';
function avatar(size=''){const photo=photoSafe(state.profile.photo);return `<span class="avatar ${size}">${photo?`<img src="${esc(photo)}" alt="Foto de perfil">`:esc(firstName().slice(0,1).toUpperCase())}</span>`;}
function brand(){return `<a class="brand" href="${state.user?'#home':'#login'}"><img class="brand-logo" src="./assets/ecoplant-logo.png" width="44" height="44" alt="Logo Ecoplant"><span><strong>Ecoplant</strong><small>CUIDAR É OBSERVAR</small></span></a>`;}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',error?6500:3600);}
function errorMessage(error){return error?.userMessage || (/^(model|classifier)\//.test(error?.code||'')?error.message:cloud.readableError(error));}
function openDialog(title,html){const d=$('#dialog');stopCamera();d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Fechar">${icon('close')}</button></div>${html}`;d.showModal();return d;}
function closeDialog(){stopCamera();$('#dialog').close();}
function authScreen(view){
 const register=view==='register',recover=view==='recover';
 return `<main class="auth"><aside class="auth-story">${brand()}<h2 class="serif">Um olhar atento.<br>Uma planta <i>mais saudável.</i></h2><p>Fotografe, descubra os sinais e acompanhe cada nova folha do seu jardim.</p><img src="./assets/garden.svg" alt="Ilustração botânica de uma planta em vaso"><footer><span>TECNOLOGIA A SERVIÇO DO VERDE</span><span>01 / SEU JARDIM COMEÇA AQUI</span></footer></aside><section class="auth-panel"><div class="auth-tools">${renderThemeSwitch()}<button class="auth-install btn secondary small" data-action="install" aria-label="Instalar Ecoplant">${icon('download')} Instalar Ecoplant</button></div><div class="auth-inner"><div class="eyebrow">${recover?'VAMOS RECUPERAR SEU ACESSO':register?'CULTIVE NOVOS HÁBITOS':'BEM-VINDO AO SEU JARDIM'}</div><h1 class="serif">${recover?'Esqueceu a senha?':register?'Crie sua conta.':'Bom te ver de novo.'}</h1><p class="intro">${recover?'Informe seu e-mail para receber o link de recuperação.':register?'Um espaço para suas plantas e para tudo o que você aprende com elas.':'Entre para acompanhar suas plantas, do primeiro registro à próxima folha.'}</p><form id="auth-form" data-view="${esc(view)}">${register?field('Nome completo','name','Seu nome',{required:true,maxlength:120,autocomplete:'name'}):''}${field('E-mail','email','voce@exemplo.com',{type:'email',required:true,autocomplete:'email'})}${recover?'':passwordField('Senha','password',register?'Crie uma senha com 8 ou mais caracteres':'Sua senha',register?'new-password':'current-password',register?8:1)}${register?passwordField('Confirmar senha','confirm','Repita a senha','new-password',8):''}${!recover?`<div class="auth-options"><label class="checkbox"><input type="checkbox" name="remember" checked>Manter conectado</label>${!register?'<a class="link" href="#recover">Esqueci minha senha</a>':''}</div>`:''}<div class="form-error" role="alert"></div><button class="btn block" type="submit">${icon(recover?'mail':register?'user':'arrow')}${recover?'Enviar link':register?'Criar conta':'Entrar'}</button></form>${!recover?`<div class="divider">OU CONTINUE COM</div><button class="btn secondary block" data-action="google"><span class="google-g" aria-hidden="true">G</span>Continuar com Google</button>`:''}<p class="auth-switch">${recover?'<a href="#login">Voltar ao login</a>':register?'Já tem uma conta? <a href="#login">Entrar</a>':'Novo por aqui? <a href="#register">Criar uma conta</a>'}</p><div class="guest-link"><button class="link" data-action="guest">Usar neste aparelho</button><small>Sem conta, os dados ficam apenas neste dispositivo.</small></div>${register?'<p class="privacy-note" style="margin-top:20px">Ao criar a conta, você permite guardar seu perfil e seus registros de plantas. Suas fotos ficam acessíveis à sua própria conta.</p>':''}</div></section></main>`;
}
function field(label,id,placeholder='',opts={}){const value=opts.value??'';const attrs=Object.entries(opts).filter(([k])=>k!=='value'&&k!=='type').map(([k,v])=>v===true?esc(k):`${esc(k)}="${esc(v)}"`).join(' ');return `<label class="field" for="${esc(id)}">${esc(label)}<input id="${esc(id)}" name="${esc(id)}" type="${esc(opts.type||'text')}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${attrs}></label>`;}
function passwordField(label,id,placeholder,autocomplete,min){return `<label class="field" for="${id}">${label}<span class="password-field"><input id="${id}" name="${id}" type="password" placeholder="${esc(placeholder)}" autocomplete="${autocomplete}" required minlength="${min}" maxlength="128"><button type="button" data-action="toggle-password" data-target="${id}" aria-label="Mostrar senha">${icon('eye')}</button></span></label>`;}
function navLink(href,label,ico,active){return `<a class="nav-link ${active?'active':''}" href="${href}">${icon(ico)}${label}${href==='#plants'&&state.plants.length?`<span class="nav-count">${state.plants.length}</span>`:''}</a>`;}
function shell(content,active='home',title='Visão geral'){
 const local=state.guest,offline=navigator.onLine===false;
 return `<div class="shell"><aside class="sidebar">${brand()}<div class="eyebrow">MEU JARDIM</div><nav>${navLink('#home','Visão geral','home',active==='home')}${navLink('#plants','Minhas plantas','plants',active==='plants')}${navLink('#history','Histórico','clock',active==='history')}${navLink('#profile','Meu perfil','user',active==='profile')}${navLink('#guide','Como usar','help',active==='guide')}</nav><div class="sidebar-bottom"><div class="install-tile">${icon('download')}<h3>Seu jardim, com você.</h3><p>${isStandalone()?'O Ecoplant já está instalado neste aparelho.':'Instale o Ecoplant na tela inicial e fique mais perto das suas plantas.'}</p><button class="btn secondary small" data-action="install">${isStandalone()?'Sobre a instalação':'Instalar aplicativo'}</button></div><a href="#profile" class="sidebar-user">${avatar()}<span><strong>${esc(name())}</strong><small>${local?'Dados neste aparelho':'Minha conta Ecoplant'}</small></span></a></div></aside><header class="topbar"><div class="breadcrumb">${icon('home')} Meu jardim <span>/</span><span>${esc(title)}</span></div><a href="#home" class="mobile-brand"><img class="mobile-logo" src="./assets/ecoplant-logo.png" width="36" height="36" alt="Logo Ecoplant"><strong>Ecoplant</strong></a><div class="topbar-right">${renderThemeSwitch()}<span class="date">${date(Date.now())}</span><span class="status-pill ${local||offline?'local':''}"><span class="status-dot"></span>${offline?'Sem conexão':local?'Neste aparelho':state.dataError?'Sincronização pendente':state.source==='cache'?'Última sincronização':'Minha conta'}</span><a href="#profile" aria-label="Meu perfil">${avatar()}</a></div></header><main class="content">${state.dataError?`<div class="notice amber app-banner">${icon('info')}<span>${esc(state.dataError)} <button class="link" data-action="retry-sync">Tentar novamente</button></span></div>`:''}${offline?`<div class="notice app-banner">${icon('info')}<span>Você está offline. Os últimos registros consultados continuam disponíveis.${state.guest?'':' Reconecte para salvar na sua conta.'}</span></div>`:''}${content}<div class="footer-caption">ECOPLANT · CADA FOLHA CONTA UMA HISTÓRIA</div></main><nav class="mobile-nav" aria-label="Navegação principal"><a href="#home" class="${active==='home'?'active':''}">${icon('home')}Início</a><a href="#plants" class="${active==='plants'?'active':''}">${icon('plants')}Plantas</a><a href="#scan" class="scan-nav" aria-label="Fotografar planta">${icon('camera')}</a><a href="#history" class="${active==='history'?'active':''}">${icon('clock')}Histórico</a><a href="#profile" class="${active==='profile'?'active':''}">${icon('user')}Perfil</a></nav></div>`;
}
function heading(eyebrow,title,description='',action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="serif">${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>${action}</div>`;}
function empty(ico,title,copy,href,label){return `<div class="empty-state"><span class="empty-icon">${icon(ico)}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p>${href?`<a class="btn secondary small" href="${esc(href)}">${icon('plus')}${esc(label)}</a>`:''}</div>`;}
function plantCard(p){const photo=photoSafe(p.photo),last=latest(p.id);return `<article class="plant-card" data-plant-search="${esc((p.name+' '+(p.species||'')+' '+(p.location||'')).toLocaleLowerCase('pt-BR'))}"><a href="#plant/${esc(p.id)}">${photo?`<img class="plant-photo" src="${esc(photo)}" alt="${esc(p.name)}" loading="lazy">`:'<div class="plant-placeholder"><img src="./assets/garden.svg" alt="Ilustração de planta"></div>'}<div class="plant-body"><h3>${esc(p.name)}</h3><p class="species">${esc(p.species||'Espécie não informada')}</p><div class="plant-meta"><span>${icon('pin')}${esc(p.location||'Meu jardim')}</span><span class="badge ${last?'amber':''}">${last?'Em acompanhamento':'Novo registro'}</span></div></div></a></article>`;}
function recordCard(a){const p=findPlant(a.plantId),photo=photoSafe(a.photo);return `<a class="record" href="#report/${esc(a.id)}">${photo?`<img class="record-thumb" src="${esc(photo)}" alt="Foto do registro" loading="lazy">`:`<span class="record-thumb">${icon('leaf')}</span>`}<div class="record-info"><h3>${esc(a.result?.topClass||a.result?.title||'Registro de observação')}</h3><p>${esc(p?.name||'Planta sem vínculo')} · ${a.result?.method==='teachable-machine'?'Teachable Machine':'Triagem por sinais'}</p><time>${date(a.date||a.createdAt)}</time></div>${icon('right')}</a>`;}
function followUpReminder(){if(state.profile.reminders===false)return '';const plant=state.plants.find(p=>{const record=latest(p.id);return record&&Date.now()-Number(record.date||record.createdAt)>3*24*60*60*1000;});return plant?`<div class="notice app-banner">${icon('clock')}<span>Que tal observar ${esc(plant.name)} novamente? Seu último registro tem mais de três dias. <a class="link" href="#scan?plant=${esc(plant.id)}">Fazer um novo registro</a></span></div>`:'';}
function home(){const now=new Date().getHours(),greeting=now<12?'Bom dia':now<18?'Boa tarde':'Boa noite';const recent=sortedAnalyses().slice(0,3);return shell(`${heading('UM NOVO DIA PARA CULTIVAR',['Meu jardim','Seu jardim'].includes(name())?'Bem-vindo ao seu jardim.':`${greeting}, ${firstName()}.`,'Que tal observar suas plantas hoje?',`<a class="btn" href="#plant/new">${icon('plus')}Nova planta</a>`)}${followUpReminder()}<section class="hero"><div class="hero-text"><div class="eyebrow">${icon('spark')} UM OLHAR MAIS DE PERTO</div><h2 class="serif">Sua planta tem<br>algo a contar.</h2><p>Fotografe uma folha e acompanhe os sinais com o seu modelo treinado.</p><a href="#scan" class="btn">${icon('camera')}Analisar minha planta</a></div><img class="hero-image" src="./assets/garden.svg" alt="Planta em vaso com folhas verdes"><span class="hero-tag">Cuidar começa por observar</span></section><div class="stats"><div class="stat"><span class="stat-icon">${icon('plants')}</span><div><strong>${state.plants.length}</strong><p>Plantas no jardim</p></div></div><div class="stat"><span class="stat-icon">${icon('file')}</span><div><strong>${state.analyses.length}</strong><p>Registros salvos</p></div></div><div class="stat"><span class="stat-icon">${icon('camera')}</span><div><strong>${new Set(state.analyses.map(a=>a.plantId).filter(Boolean)).size}</strong><p>Em acompanhamento</p></div></div></div><div class="home-grid"><section><div class="section-head"><h2>Seu pequeno jardim</h2><a class="link" href="#plants">Ver todas</a></div>${state.plants.length?`<div class="plant-grid">${state.plants.slice(0,2).map(plantCard).join('')}</div>`:`<div class="panel">${empty('plants','O primeiro broto é seu.','Adicione uma planta para guardar fotos, observações e relatórios.','#plant/new','Adicionar primeira planta')}</div>`}</section><section><div class="section-head"><h2>Para observar melhor</h2><a class="link" href="#guide">Como funciona</a></div><div class="panel"><div class="tips-item">${icon('sun')}<div><h3>Boa luz faz a diferença</h3><p>Prefira iluminação natural e evite sombras sobre a folha.</p></div></div><div class="tips-item">${icon('camera')}<div><h3>Uma folha por vez</h3><p>Mostre os detalhes e mantenha a câmera firme e próxima.</p></div></div><div class="tips-item">${icon('clock')}<div><h3>Observe ao longo dos dias</h3><p>Use fotos com o mesmo enquadramento para comparar os registros.</p></div></div></div></section></div>${recent.length?`<section style="margin-top:30px"><div class="section-head"><h2>Últimos registros</h2><a href="#history" class="link">Ver histórico</a></div><div class="timeline">${recent.map(recordCard).join('')}</div></section>`:''}`);}
function plantsView(){return shell(`${heading('CADA PLANTA, UMA HISTÓRIA','Minhas plantas','Um espaço para conhecer e cuidar do seu jardim.',`<a class="btn" href="#plant/new">${icon('plus')}Adicionar planta</a>`)}${state.plants.length?`<div class="toolbar"><label class="search">${icon('search')}<input data-search placeholder="Buscar por nome, espécie ou local" aria-label="Buscar plantas"></label><span>${state.plants.length} planta${state.plants.length>1?'s':''} no jardim</span></div><div class="plant-grid">${state.plants.map(plantCard).join('')}</div><p id="search-empty" class="muted hidden" style="padding:30px;text-align:center;font-size:12px">Nenhuma planta encontrada.</p>`:`<div class="panel">${empty('plants','Seu jardim começa aqui','Dê um nome à sua planta e adicione a primeira foto.','#plant/new','Cadastrar uma planta')}</div>`}`,'plants','Minhas plantas');}
function plantForm(id){const p=id?findPlant(id):null;if(id&&!p)return missing();const photo=state.plantPhoto??p?.photo;return shell(`${heading('UM NOVO CAPÍTULO NO JARDIM',p?'Editar planta':'Nova planta','Guarde os detalhes que tornam essa planta única.')}<div class="form-layout"><section class="panel form-panel"><form id="plant-form" data-id="${esc(id||'')}"><label class="upload-box ${photoSafe(photo)?'has-photo':''}">${photoSafe(photo)?`<img src="${esc(photo)}" alt="Foto da planta"><span class="upload-label">Trocar foto</span>`:`${icon('camera')}<span><h3>Adicionar uma foto</h3><p>Uma boa foto ajuda a acompanhar a evolução.</p></span>`}<input type="file" accept="image/*" data-upload="plant" hidden></label>${photoSafe(photo)?'<button type="button" class="link" data-action="remove-plant-photo">Remover foto</button>':''}${field('Nome da planta','plant-name','Ex.: Meu tomateiro',{required:true,maxlength:120,value:p?.name})}<div class="form-grid">${field('Espécie (opcional)','species','Ex.: Solanum lycopersicum',{maxlength:180,value:p?.species})}${field('Local de cultivo (opcional)','location','Ex.: Horta de casa',{maxlength:180,value:p?.location})}</div><label class="field">Observações (opcional)<textarea name="notes" maxlength="4000" placeholder="Anote os detalhes da sua planta">${esc(p?.notes||'')}</textarea></label><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="btn">${icon('check')}Salvar planta</button><a class="btn secondary" href="${p?'#plant/'+esc(p.id):'#plants'}">Cancelar</a></div></form></section><aside class="info-aside"><img src="./assets/garden.svg" alt="Ilustração botânica"><div class="eyebrow">PRIMEIRO, CONHECER</div><h3>Cada detalhe importa.</h3><p>Registre o local, a espécie e as mudanças que você percebe. Seu histórico ajuda a acompanhar o desenvolvimento da planta.</p></aside></div>`,'plants',p?'Editar planta':'Cadastrar planta');}
function plantDetail(id){const p=findPlant(id);if(!p)return missing();const records=sortedAnalyses().filter(a=>a.plantId===id);const photo=photoSafe(p.photo);return shell(`${heading(p.species||'MEU JARDIM',p.name,p.location||'Sua planta no Ecoplant',`<a class="btn secondary small" href="#plant/${esc(id)}/edit">${icon('edit')}Editar</a>`)}<div class="detail-layout"><section><div class="detail-photo ${photo?'':'placeholder'}"><img src="${photo?esc(photo):'./assets/garden.svg'}" alt="${esc(p.name)}"></div><div class="detail-info"><span class="badge">${icon('plants')}${records.length} registro${records.length===1?'':'s'}</span><dl><dt>No jardim desde</dt><dd>${date(p.createdAt)}</dd><dt>Local</dt><dd>${esc(p.location||'Não informado')}</dd><dt>Espécie</dt><dd>${esc(p.species||'Não informada')}</dd></dl>${p.notes?`<p class="detail-notes">${esc(p.notes)}</p>`:''}<button class="link" data-action="delete-plant" data-id="${esc(id)}" style="margin-top:25px;color:var(--red)">Excluir planta e registros</button></div></section><section><div class="section-head"><h2>Uma folha de cada vez</h2></div><a class="btn block" href="#scan?plant=${esc(id)}">${icon('camera')}Nova análise</a><div class="section-head" style="margin-top:27px"><h2>Histórico da planta</h2>${records.length>1?`<button class="link" data-action="compare" data-id="${esc(id)}">Comparar fotos</button>`:''}</div>${records.length?`<div class="timeline">${records.map(recordCard).join('')}</div>`:`<div class="panel">${empty('clock','Ainda sem registros','Fotografe uma folha para começar o acompanhamento.','','')}</div>`}</section></div>`,'plants',p.name);}
function historyView(){return shell(`${heading('O TEMPO TAMBÉM CUIDA','Histórico','Revisite as fotos, os sinais e os relatórios das suas plantas.',`<a class="btn" href="#scan">${icon('camera')}Novo registro</a>`)}${state.analyses.length?`<div class="toolbar"><label class="field" style="min-width:200px">Filtrar por planta<select id="history-filter"><option value="">Todas as plantas</option>${state.plants.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><span>${state.analyses.length} registros salvos</span></div><div class="timeline">${sortedAnalyses().map(a=>`<div data-record-plant="${esc(a.plantId||'')}">${recordCard(a)}</div>`).join('')}</div>`:`<div class="panel">${empty('clock','A história ainda vai começar','Seus registros e relatórios aparecerão aqui após a primeira avaliação.','#scan','Registrar uma observação')}</div>`}`,'history','Histórico');}
function scanView(){const chosen=state.scanPlantId||routeParams().get('plant')||'',hasModel=!!state.profile.modelURL;return shell(`${heading('OBSERVE. REGISTRE. ACOMPANHE.','Um olhar mais de perto','Uma boa foto é o primeiro passo para entender os sinais.')}<div class="scan-layout"><section><div class="scan-step">01 / A FOTO DA FOLHA</div><div class="scan-photo">${photoSafe(state.scanPhoto)?`<img src="${esc(state.scanPhoto)}" alt="Folha selecionada para avaliação">`:`<div class="scan-placeholder">${icon('camera')}<h3>Vamos observar uma folha?</h3><p>Use luz natural, um fundo simples e mantenha os detalhes em foco.</p></div>`}</div><div class="photo-controls"><button class="btn" data-action="open-camera">${icon('camera')}Abrir câmera</button><label class="btn secondary">${icon('gallery')}Galeria<input type="file" accept="image/*" data-upload="scan" hidden></label></div><input type="file" id="camera-fallback" accept="image/*" capture="environment" data-upload="scan" hidden><div class="notice">${icon('info')}<span>A foto fica no seu histórico. No modo Teachable Machine, a identificação é feita pelo modelo que você conectar.</span></div></section><section class="panel scan-panel"><div class="scan-step">02 / O CONTEXTO DA PLANTA</div><form id="scan-form"><label class="field">De qual planta é esta folha?<select name="plantId" required><option value="">Selecione uma planta</option>${state.plants.map(p=>`<option value="${esc(p.id)}" ${p.id===chosen?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${!state.plants.length?'<div class="notice amber" style="margin-bottom:18px">Cadastre uma planta para vincular a foto. <a class="link" href="#plant/new">Cadastrar planta</a></div>':''}<label class="field">Como deseja avaliar?<select name="method" id="analysis-method"><option value="teachable-machine" ${hasModel?'':'disabled'} ${hasModel&&state.scanMethod!=='guided'?'selected':''}>Identificação pelo Teachable Machine${hasModel?'':' — conecte o modelo'}</option><option value="guided" ${!hasModel||state.scanMethod==='guided'?'selected':''}>Triagem pelos sinais que eu observar</option></select></label>${!hasModel?'<div class="notice amber" style="margin-bottom:20px"><span>Conecte seu modelo treinado para identificar a foto automaticamente. <a class="link" href="#profile">Configurar modelo</a></span></div>':'<div class="notice" style="margin-bottom:20px"><span>Seu modelo treinado está configurado. Use fotos semelhantes às imagens usadas no treinamento.</span></div>'}<h2 class="serif">O que você está vendo?</h2><p style="font-size:11px;color:var(--muted);line-height:1.8;margin:8px 0 16px">Os sinais são opcionais no modo automático e ajudam a completar o relatório.</p><div class="symptom-grid">${SYMPTOMS.map(s=>`<label class="symptom"><input type="checkbox" name="symptom" value="${esc(s.id)}" ${state.scanSymptoms.includes(s.id)?'checked':''}>${esc(s.label)}</label>`).join('')}</div><label class="field">Suas observações (opcional)<textarea name="notes" maxlength="4000" placeholder="Quando os sinais apareceram? O que mudou nos cuidados?">${esc(state.scanNotes)}</textarea></label><div class="form-error" role="alert"></div><button class="btn block" type="submit" ${state.plants.length?'':'disabled'}>${icon('spark')}Gerar relatório da planta</button><p class="privacy-note" style="margin-top:13px">A triagem por sinais usa apenas as informações que você marcar. A identificação automática depende das classes e da qualidade do modelo treinado.</p></form></section></div>`,'plants','Analisar planta');}
function profileView(){const p=state.profile;return shell(`${heading('SEU ESPAÇO VERDE','Meu perfil','Seus dados, preferências e modelo de identificação.')}<div class="form-layout"><section class="panel form-panel"><div class="profile-header">${avatar()}<div><h2>${esc(name())}</h2><p>${esc(state.guest?'Conta local neste aparelho':state.user?.email||'Conta Google')}</p><label class="link" style="display:block;margin-top:7px;font-size:10px">Alterar foto<input type="file" accept="image/*" data-upload="profile" hidden></label></div></div><form id="profile-form">${field('Nome','displayName','Seu nome',{required:true,maxlength:120,value:p.displayName||p.name||state.user?.displayName||''})}${!state.guest?field('E-mail','profile-email','',{type:'email',value:state.user?.email||'',readonly:true}):''}<label class="checkbox"><input type="checkbox" name="reminders" ${p.reminders!==false?'checked':''}>Exibir lembretes de acompanhamento no aplicativo</label><button class="btn block" type="submit">${icon('check')}Salvar alterações</button><div class="form-error" role="alert"></div></form><div class="settings-list"><button class="setting" data-action="reset-password">${icon('lock')}Recuperar / alterar senha${icon('right')}</button><button class="setting" data-action="install">${icon('download')}Instalar no celular${icon('right')}</button><a class="setting" href="#guide">${icon('help')}Como usar o Ecoplant${icon('right')}</a><button class="setting" data-action="export-data">${icon('file')}Exportar meus registros${icon('right')}</button><button class="setting" data-action="logout" style="color:var(--red)">${icon('logout')}${state.guest?'Voltar para o login':'Sair da conta'}${icon('right')}</button></div></section><section class="panel form-panel"><div class="eyebrow" style="margin-bottom:10px">INTELIGÊNCIA TREINADA POR VOCÊ</div><h2 class="serif">Teachable Machine</h2><p class="muted" style="font-size:12px;line-height:1.8;margin-bottom:22px">Publique seu modelo de imagem e conecte o link da pasta. Ele será usado para analisar as fotos das folhas.</p><form id="model-form">${field('Link do modelo publicado','modelURL','https://teachablemachine.withgoogle.com/models/SEU_ID/',{type:'url',required:true,maxlength:300,value:p.modelURL||''})}${field('Nome exato da classe saudável (opcional)','healthyClass','Ex.: Saudável',{maxlength:200,value:p.healthyClass||''})}<p class="privacy-note">Informe uma classe que exista no seu treinamento. A confiança indica a escolha do modelo, não a gravidade de uma doença.</p><div class="form-error" role="alert"></div><button class="btn block" type="submit">${icon('spark')}Validar e conectar modelo</button>${p.modelURL?'<button class="link" type="button" data-action="remove-model">Desconectar modelo</button>':''}<div id="model-status" class="notice ${state.model?'':'hidden'}">${state.model?esc('Modelo conectado · '+state.model.labels.join(', ')):''}</div></form><div class="tips-item" style="margin-top:25px">${icon('camera')}<div><h3>Seu treinamento faz a diferença</h3><p>Inclua diferentes folhas, fundos e iluminações. Separe fotos novas para verificar o desempenho antes de usar os resultados.</p></div></div><a class="link" href="https://teachablemachine.withgoogle.com/train/image" target="_blank" rel="noopener noreferrer" style="display:inline-block;margin-top:16px">Abrir Teachable Machine ↗</a></section></div>`,'profile','Meu perfil');}
function guideView(){return shell(`${heading('UM GUIA PARA COMEÇAR','Cuidar, um passo de cada vez.','Conheça o caminho da primeira foto ao relatório da sua planta.')}<div class="form-layout"><section><div class="panel help-card"><h3>1. Adicione suas plantas</h3><p>Escolha um nome, informe a espécie e o local de cultivo e adicione uma foto. Cada planta terá seu próprio histórico.</p><a class="btn secondary small" href="#plant/new" style="margin-top:15px">Cadastrar planta</a></div><div class="panel help-card"><h3>2. Conecte o modelo treinado</h3><p>No Teachable Machine, crie um projeto de imagem. Treine as classes de plantas saudáveis e das condições que deseja distinguir. Em <strong>Exportar modelo → Tensorflow.js → Fazer upload</strong>, copie o link da pasta e cole no perfil do Ecoplant.</p><p style="margin-top:12px">Teste com fotos que não foram usadas no treinamento. O modelo só reconhece as classes que você ensinou e pode errar com outras espécies, fundos ou condições.</p><a class="btn secondary small" href="#profile" style="margin-top:15px">Conectar modelo</a></div><div class="panel help-card"><h3>3. Fotografe e gere o relatório</h3><p>Abra a câmera, permita o acesso e capture uma folha bem iluminada. Você também pode escolher uma imagem da galeria. Selecione a planta, acrescente observações e gere o relatório.</p></div><div class="panel help-card"><h3>4. Acompanhe a evolução</h3><p>Salve os relatórios e faça novos registros ao longo dos dias. Na ficha da planta, use <strong>Comparar fotos</strong> para observar a primeira e a mais recente. No relatório, <strong>Imprimir / PDF</strong> permite exportar pelo navegador.</p></div></section><aside><div class="panel help-card"><h3>Instalar no Android</h3><p>Abra no Chrome e toque em <strong>Instalar aplicativo</strong>. Se a opção não aparecer, abra o menu de três pontos e escolha <strong>Instalar aplicativo</strong> ou <strong>Adicionar à tela inicial</strong>.</p><button class="btn secondary small" data-action="install" style="margin-top:15px">${icon('download')}Instalar Ecoplant</button></div><div class="panel help-card"><h3>Instalar no iPhone</h3><p>Abra o endereço no Safari. Toque em <strong>Compartilhar → Adicionar à Tela de Início → Adicionar</strong>. Ative <strong>Abrir como App da Web</strong>, quando disponível.</p></div><div class="panel help-card"><h3>Seus dados e suas fotos</h3><p>Na conta, os registros são sincronizados quando há internet. No modo <strong>Neste aparelho</strong>, os dados ficam apenas no navegador atual. Você pode exportá-los no perfil. Limpar os dados do navegador pode apagar os registros locais.</p></div><div class="notice">${icon('info')}<span>O Ecoplant apoia a observação. Uma classe identificada pelo modelo é uma hipótese e pode precisar de confirmação por um profissional.</span></div></aside></div>`,'guide','Como usar');}
function missing(){return shell(`${heading('MEU JARDIM','Registro não encontrado','Este item pode ter sido excluído ou pertencer a outra conta.')}<a class="btn" href="#plants">Voltar às plantas</a>`,'plants','Registro');}
function render(){
 const path=routePath();let html;
 const oldForm=lastRenderedRoute===currentRoute()?$('#plant-form, #profile-form, #model-form, #scan-form'):null;
 const savedFields=oldForm?[...oldForm.querySelectorAll('[name]')].filter(el=>el.type!=='file').map(el=>({name:el.name,type:el.type,value:el.value,checked:el.checked})):[];
 const focused=oldForm?.contains(document.activeElement)?document.activeElement.name:null;
 if(!state.user){html=authScreen(['login','register','recover'].includes(path)?path:'login');}
 else if(path==='plants')html=plantsView();
 else if(path==='plant/new')html=plantForm();
 else if(/^plant\//.test(path)){const [,id,edit]=path.split('/');html=edit==='edit'?plantForm(id):plantDetail(id);}
 else if(path==='history')html=historyView();
 else if(path==='profile')html=profileView();
 else if(path==='scan')html=scanView();
 else if(path==='guide')html=guideView();
 else if(/^report\//.test(path)){const id=path.split('/')[1],record=id==='draft'?state.draft:state.analyses.find(a=>a.id===id);html=record?shell(reportHTML(record,findPlant(record.plantId),state.profile,{draft:id==='draft'}),'history','Relatório'):missing();}
 else html=home();
 $('#app').innerHTML=html;
 if(oldForm){const form=document.getElementById(oldForm.id);if(form){for(const el of form.querySelectorAll('[name]')){const prior=savedFields.find(f=>f.name===el.name&&(el.type!=='checkbox'||f.value===el.value));if(!prior)continue;if(el.type==='checkbox'||el.type==='radio')el.checked=prior.checked;else if(el.type!=='file')el.value=prior.value;}if(focused){const input=[...form.querySelectorAll('[name]')].find(el=>el.name===focused);input?.focus({preventScroll:true});}}}
 for(const id of pendingForms){const submit=document.querySelector(`#${id} [type="submit"]`);if(submit){submit.disabled=true;submit.innerHTML=`${loaderHTML({small:true})} Só um instante…`;}}
 lastRenderedRoute=currentRoute();
}
async function loadGuest(){unsubscribeData();state.guest=true;let uid=localStorage.getItem('ecoplant-guest-id');if(!uid){uid='local-'+uuid();localStorage.setItem('ecoplant-guest-id',uid);}state.user={uid,displayName:'Meu jardim',email:''};const data=await getCachedData(uid)||blankData();Object.assign(state,data,{source:'local',dataError:''});state.profile.displayName ||= 'Meu jardim';go('#home');render();finishSplash();}
async function persistLocal(data){const stored=await putCachedData(state.user.uid,data);if(!stored)throw Object.assign(new Error(),{userMessage:'Este navegador bloqueou o armazenamento local. Permita os dados deste site para salvar seus registros.'});Object.assign(state,data);render();}
async function saveProfile(patch){if(state.guest){await persistLocal({...blankData(),profile:{...state.profile,...patch},plants:state.plants,analyses:state.analyses});}else{await cloud.saveProfile(state.user.uid,patch);state.profile={...state.profile,...patch};render();}}
async function savePlant(record){if(state.guest){await persistLocal({profile:state.profile,plants:[record,...state.plants.filter(p=>p.id!==record.id)],analyses:state.analyses});return record;}const saved=await cloud.savePlant(state.user.uid,record);state.plants=[saved,...state.plants.filter(p=>p.id!==saved.id)];return saved;}
async function saveAnalysis(record){if(state.guest){await persistLocal({profile:state.profile,plants:state.plants,analyses:[record,...state.analyses.filter(a=>a.id!==record.id)]});return record;}const saved=await cloud.saveAnalysis(state.user.uid,record);state.analyses=[saved,...state.analyses.filter(a=>a.id!==saved.id)];return saved;}
async function activateUser(user){if(state.guest)return;unsubscribeData();if(state.user?.uid!==user?.uid){lastRenderedRoute='';state.scanPhoto='';state.scanSymptoms=[];state.scanNotes='';state.draft=null;state.model=null;state.scanPlantId='';state.scanMethod='';state.plantPhoto=null;state.profilePhoto=null;}state.user=user;state.profile={};state.plants=[];state.analyses=[];state.dataError='';authResolved=true;if(!user){render();finishSplash();return;}state.profile.displayName=user.displayName||'';state.profile.email=user.email||'';unsubscribeData=cloud.subscribeData(user.uid,data=>{if(state.user?.uid!==user.uid||state.guest)return;Object.assign(state,{...data,profile:{displayName:user.displayName||'',email:user.email||'',...data.profile},dataError:''});render();},error=>{state.dataError=errorMessage(error);render();});if(['login','register','recover',''].includes(routePath()))go('#home');render();finishSplash();try{if(cloud.ensureProfile)await cloud.ensureProfile(user);}catch(error){state.dataError=errorMessage(error);render();}}
async function resizeImage(file){if(!file||file.size>15*1024*1024)throw new Error('Escolha uma imagem de até 15 MB.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('Este formato não abriu no navegador. Use uma foto JPG, PNG ou WebP.'));img.src=url;});return canvasPhoto(img);}finally{URL.revokeObjectURL(url);}}
function canvasPhoto(source){const width=source.videoWidth||source.naturalWidth||source.width,height=source.videoHeight||source.naturalHeight||source.height;if(!width||!height)throw new Error('A câmera ainda está preparando a imagem. Tente novamente.');const scale=Math.min(1,850/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);let q=.82,data=canvas.toDataURL('image/jpeg',q);while(data.length>230000&&q>.25){q-=.08;data=canvas.toDataURL('image/jpeg',q);}if(data.length>240000)throw new Error('A imagem ficou muito grande. Aproxime-se de uma única folha e tente de novo.');return data;}
function stopCamera(){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;}
async function openCamera(){const d=openDialog('Fotografar uma folha',`<div class="camera-view"><video id="camera-video" autoplay playsinline muted style="display:block;width:100%;aspect-ratio:1;object-fit:cover;border-radius:13px;background:#173e32"></video><p class="privacy-note" style="margin:12px 0">Uma folha por vez. Mantenha a câmera firme e use boa iluminação.</p><div class="form-actions"><button class="btn" data-action="capture-photo">${icon('camera')}Fotografar</button><button class="btn secondary" data-action="flip-camera" aria-label="Alternar câmera">${icon('switch')}</button></div><div id="camera-message" class="form-error" role="alert"></div></div>`);try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Câmera indisponível neste navegador.');const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:cameraFacing},width:{ideal:1280},height:{ideal:1280}},audio:false});if(!d.open){stream.getTracks().forEach(t=>t.stop());return;}cameraStream=stream;const v=$('#camera-video');v.srcObject=stream;await v.play();}catch(error){stopCamera();const m=$('#camera-message');if(m)m.innerHTML=`${esc(error.name==='NotAllowedError'?'Permita o acesso à câmera nas configurações do navegador ou use uma foto da galeria.':error.message||'Não foi possível abrir a câmera.')}<br><button class="link" data-action="camera-file" style="margin-top:10px">Usar câmera do aparelho / galeria</button>`;}}
function getCurrentReport(){return routePath()==='report/draft'?state.draft:state.analyses.find(a=>a.id===routePath().split('/')[1]);}
async function install(){const result=await installApp();if(result.installed){toast('Ecoplant instalado. Encontre o ícone na tela inicial.');return;}if(result.dismissed||result.outcome==='dismissed')return;const instructions=Array.isArray(result.instructions)?result.instructions:[result.instructions||'Abra o menu do navegador e escolha Instalar aplicativo ou Adicionar à tela inicial.'];openDialog(isStandalone()?'Ecoplant no seu aparelho':'Instalar Ecoplant',`<p class="dialog-copy">${isStandalone()?'Você já está usando o aplicativo pela tela inicial.':'Tenha seu jardim a um toque de distância.'}</p><ol class="install-steps">${instructions.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><button class="btn block" data-action="close-dialog">Entendi</button>`);}
function downloadJSON(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 const loadingActions={google:'Conectando sua conta Google…','confirm-reset':'Enviando o link de recuperação…','retry-sync':'Sincronizando seu jardim…','save-report':'Salvando seu relatório…','confirm-delete-plant':'Excluindo a planta e os registros…','confirm-delete-report':'Excluindo o relatório…',guest:'Abrindo seu jardim neste aparelho…'};
 const clickLoadingToken=loadingActions[action]?showLoading(loadingActions[action]):null;
 try{
  if(action==='toggle-password'){const input=document.getElementById(b.dataset.target);input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?'Mostrar senha':'Ocultar senha');return;}
  if(action==='close-dialog'){closeDialog();return;}
  if(action==='guest'){await loadGuest();return;}
  if(action==='install'){await install();return;}
  if(action==='google'){b.disabled=true;const remember=$('[name="remember"]')?.checked!==false;try{await cloud.loginGoogle(remember);}finally{if(b.isConnected)b.disabled=false;}return;}
  if(action==='open-camera'){await openCamera();return;}
  if(action==='flip-camera'){cameraFacing=cameraFacing==='environment'?'user':'environment';closeDialog();await openCamera();return;}
  if(action==='capture-photo'){state.scanPhoto=canvasPhoto($('#camera-video'));closeDialog();render();return;}
  if(action==='camera-file'){closeDialog();$('#camera-fallback')?.click();return;}
  if(action==='remove-plant-photo'){state.plantPhoto='';render();return;}
  if(action==='logout'){unsubscribeData();stopCamera();const wasGuest=state.guest;state.guest=false;state.user=null;lastRenderedRoute='';Object.assign(state,blankData(),{dataError:'',model:null,scanPhoto:'',scanSymptoms:[],scanNotes:'',scanPlantId:'',scanMethod:'',draft:null});if(!wasGuest)await cloud.logout();go('#login');render();return;}
  if(action==='retry-sync'){state.dataError='';if(!state.guest)await activateUser(state.user);return;}
  if(action==='reset-password'){if(state.guest){toast('Entre em uma conta para recuperar a senha.');return;}openDialog('Alterar sua senha',`<p class="dialog-copy">Vamos enviar um link de recuperação para <strong>${esc(state.user.email||'seu e-mail')}</strong>. Se você entra com Google, sua senha é gerenciada pela conta Google.</p><button class="btn block" data-action="confirm-reset">Enviar link de recuperação</button>`);return;}
  if(action==='confirm-reset'){b.disabled=true;await cloud.recover(state.user.email);closeDialog();toast('Se o e-mail estiver cadastrado para senha, você receberá o link.');return;}
  if(action==='remove-model'){await saveProfile({modelURL:'',healthyClass:''});state.model=null;toast('Modelo desconectado.');render();return;}
  if(action==='export-data'){downloadJSON({app:'Ecoplant',exportedAt:new Date().toISOString(),profile:state.profile,plants:state.plants,analyses:state.analyses},'ecoplant-meu-jardim.json');return;}
  if(action==='delete-plant'){openDialog('Excluir esta planta?',`<p class="dialog-copy">${esc(findPlant(id)?.name)} e os relatórios vinculados serão excluídos. Esta ação não pode ser desfeita.</p><button class="btn danger block" data-action="confirm-delete-plant" data-id="${esc(id)}">${icon('trash')}Excluir planta e relatórios</button>`);return;}
  if(action==='confirm-delete-plant'){b.disabled=true;const records=state.analyses.filter(a=>a.plantId===id);if(state.guest){await persistLocal({profile:state.profile,plants:state.plants.filter(p=>p.id!==id),analyses:state.analyses.filter(a=>a.plantId!==id)});}else{for(const a of records)await cloud.deleteAnalysis(state.user.uid,a.id);await cloud.deletePlant(state.user.uid,id);state.plants=state.plants.filter(p=>p.id!==id);state.analyses=state.analyses.filter(a=>a.plantId!==id);}closeDialog();go('#plants');toast('Planta excluída.');return;}
  if(action==='save-report'){if(!state.draft)return;b.disabled=true;const record=await saveAnalysis(state.draft);state.draft=null;go('#report/'+record.id);toast(state.guest?'Relatório salvo neste aparelho.':'Relatório salvo na sua conta.');return;}
  if(action==='export-report'){const a=getCurrentReport();if(!a)return;const plant=findPlant(a.plantId);openDialog('Exportar relatório',`<p class="dialog-copy">${esc(plant?.name||'Sua planta')} · ${date(a.date||a.createdAt)}<br>O relatório continua disponível aqui no aplicativo. Escolha como deseja exportar.</p><div style="display:grid;gap:12px"><button class="btn block" data-action="print-report">${icon('file')}PDF · salvar ou imprimir</button><button class="btn secondary block" data-action="download-report">${icon('download')}JSON · exportar os dados</button></div><p class="privacy-note" style="margin-top:16px">Para PDF, escolha Salvar como PDF ou Compartilhar na janela de impressão do aparelho.</p>`);return;}
  if(action==='print-report'){if($('#dialog').open)closeDialog();window.print();return;}
  if(action==='download-report'){const a=getCurrentReport();if(a)downloadReport(a,findPlant(a.plantId));if($('#dialog').open)closeDialog();return;}
  if(action==='delete-report'){const a=getCurrentReport();if(!a)return;openDialog('Excluir este relatório?',`<p class="dialog-copy">O registro de ${date(a.date)} será excluído do histórico.</p><button class="btn danger block" data-action="confirm-delete-report" data-id="${esc(a.id)}">Excluir relatório</button>`);return;}
  if(action==='confirm-delete-report'){if(state.guest)await persistLocal({profile:state.profile,plants:state.plants,analyses:state.analyses.filter(a=>a.id!==id)});else await cloud.deleteAnalysis(state.user.uid,id);closeDialog();go('#history');toast('Relatório excluído.');return;}
  if(action==='compare'){const records=sortedAnalyses().filter(a=>a.plantId===id&&photoSafe(a.photo));if(records.length<2){toast('Adicione pelo menos duas fotos para comparar.');return;}const old=records.at(-1),recent=records[0];openDialog('Evolução da planta',`<p class="dialog-copy">${esc(findPlant(id)?.name||'Sua planta')} · Compare os registros visuais. As fotos não medem a gravidade da condição.</p><div class="compare-grid"><section><img src="${esc(old.photo)}" alt="Primeira foto"><p>Primeira foto · ${date(old.date)}</p></section><section><img src="${esc(recent.photo)}" alt="Foto mais recente"><p>Mais recente · ${date(recent.date)}</p></section></div>`);return;}
 }catch(error){if(b.isConnected)b.disabled=false;toast(errorMessage(error),true);}
 finally{if(clickLoadingToken!==null)hideLoading(clickLoadingToken);}
});
document.addEventListener('submit',async e=>{
 const operationUID=state.user?.uid;const form=e.target;if(!['auth-form','plant-form','profile-form','model-form','scan-form'].includes(form.id))return;e.preventDefault();if(pendingForms.has(form.id))return;pendingForms.add(form.id);const loadingToken=showLoading(form.id==='scan-form'?'Preparando o relatório da planta…':form.id==='model-form'?'Conectando seu modelo…':form.id==='auth-form'?'Conectando sua conta…':'Salvando seu jardim…');const data=new FormData(form),button=form.querySelector('[type="submit"]'),original=button?.innerHTML,err=form.querySelector('.form-error');if(err)err.textContent='';if(button){button.disabled=true;button.innerHTML=`${loaderHTML({small:true})} Só um instante…`;}
 try{
  if(form.id==='auth-form'){const view=form.dataset.view,email=data.get('email'),password=data.get('password'),remember=data.get('remember')==='on';if(view==='register'){if(password!==data.get('confirm'))throw Object.assign(new Error(),{userMessage:'As senhas precisam ser iguais.'});await cloud.register(data.get('name'),email,password,remember);}else if(view==='recover'){await cloud.recover(email);openDialog('Confira sua caixa de entrada',`<p class="dialog-copy">Se o e-mail estiver cadastrado, você receberá um link para redefinir sua senha. Confira também o spam.</p><button class="btn block" data-action="close-dialog">Entendi</button>`);}else await cloud.login(email,password,remember);}
  if(form.id==='plant-form'){const old=findPlant(form.dataset.id),record={id:old?.id||uuid(),name:String(data.get('plant-name')).trim(),species:String(data.get('species')||'').trim(),location:String(data.get('location')||'').trim(),notes:String(data.get('notes')||'').trim(),photo:state.plantPhoto??old?.photo??'',createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};if(!record.name)throw Object.assign(new Error(),{userMessage:'Informe o nome da planta.'});await savePlant(record);state.plantPhoto=null;go('#plant/'+record.id);toast(state.guest?'Planta salva neste aparelho.':'Planta salva no seu jardim.');}
  if(form.id==='profile-form'){const displayName=String(data.get('displayName')||'').trim();if(!state.guest)await cloud.updateUserProfile({displayName});await saveProfile({displayName,reminders:data.get('reminders')==='on',...(state.profilePhoto?{photo:state.profilePhoto}:{})});state.profilePhoto=null;toast('Seu perfil foi atualizado.');}
  if(form.id==='model-form'){const url=validateModelURL(data.get('modelURL')),healthyClass=String(data.get('healthyClass')||'').trim();const info=await loadPlantModel(url,msg=>{updateLoading(typeof msg==='string'?msg:'Carregando modelo…',loadingToken);if(button?.isConnected)button.textContent=typeof msg==='string'?msg:'Carregando modelo…';});if(healthyClass&&!info.labels.includes(healthyClass))throw Object.assign(new Error(),{userMessage:'A classe saudável precisa ter o mesmo nome de uma das classes do modelo: '+info.labels.join(', ')});if(state.user?.uid!==operationUID)return;await saveProfile({modelURL:url,healthyClass});state.model=info;render();toast('Modelo validado e conectado.');}
  if(form.id==='scan-form'){const plantId=String(data.get('plantId')||'');if(!findPlant(plantId))throw Object.assign(new Error(),{userMessage:'Selecione uma planta cadastrada.'});if(!state.scanPhoto)throw Object.assign(new Error(),{userMessage:'Fotografe uma folha ou escolha uma imagem da galeria.'});state.scanSymptoms=data.getAll('symptom');state.scanNotes=String(data.get('notes')||'');const method=data.get('method');let result;if(method==='teachable-machine'){if(!state.profile.modelURL)throw Object.assign(new Error(),{userMessage:'Conecte o modelo do Teachable Machine no seu perfil.'});const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=state.scanPhoto;});result=await classifyPlant(image,state.profile.modelURL,msg=>{updateLoading(typeof msg==='string'?msg:'Analisando a folha…',loadingToken);if(button?.isConnected)button.innerHTML=`${loaderHTML({small:true})}${esc(typeof msg==='string'?msg:'Analisando a folha…')}`;});}else{if(!state.scanSymptoms.length)throw Object.assign(new Error(),{userMessage:'Marque ao menos um sinal para a triagem guiada.'});result=evaluateSymptoms(state.scanSymptoms);}if(state.user?.uid!==operationUID)return;state.draft={id:uuid(),plantId,photo:state.scanPhoto,date:Date.now(),symptoms:state.scanSymptoms,result,notes:state.scanNotes,createdAt:Date.now(),updatedAt:Date.now()};go('#report/draft');}
 }catch(error){const message=errorMessage(error);if(err?.isConnected)err.textContent=message;else toast(message,true);}
 finally{hideLoading(loadingToken);pendingForms.delete(form.id);const current=document.querySelector(`#${form.id} [type="submit"]`);if(current){current.disabled=false;current.innerHTML=original;}}
});
document.addEventListener('change',async e=>{
 const input=e.target;
 if(input.matches('[data-upload]')){if(!input.files?.[0])return;try{const image=await resizeImage(input.files[0]);if(input.dataset.upload==='scan'){state.scanPhoto=image;}else if(input.dataset.upload==='plant'){// Preserve typed fields while repainting the photograph.
 const form=$('#plant-form'),values=form?new FormData(form):null;state.plantPhoto=image;render();if(values)for(const [key,val] of values){const element=$(`[name="${key}"]`);if(element&&typeof val==='string')element.value=val;}return;
 }else{state.profilePhoto=image;await saveProfile({photo:image});state.profilePhoto=null;toast('Foto do perfil atualizada.');}render();}catch(error){toast(error.message||'Não foi possível abrir a imagem.',true);}return;}
 if(input.name==='plantId')state.scanPlantId=input.value;
 if(input.id==='analysis-method')state.scanMethod=input.value;
 if(input.id==='history-filter'){document.querySelectorAll('[data-record-plant]').forEach(el=>el.hidden=!!input.value&&el.dataset.recordPlant!==input.value);}
 if(input.name==='symptom'){const boxes=[...document.querySelectorAll('[name="symptom"]')];if(input.value==='healthy'&&input.checked)boxes.filter(b=>b!==input).forEach(b=>b.checked=false);else if(input.checked)boxes.find(b=>b.value==='healthy')?.removeAttribute('checked');const healthy=boxes.find(b=>b.value==='healthy');if(input.value!=='healthy'&&input.checked&&healthy)healthy.checked=false;state.scanSymptoms=boxes.filter(b=>b.checked).map(b=>b.value);}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-search]')){const q=e.target.value.toLocaleLowerCase('pt-BR').trim();let count=0;document.querySelectorAll('[data-plant-search]').forEach(el=>{el.hidden=!el.dataset.plantSearch.includes(q);if(!el.hidden)count++;});$('#search-empty')?.classList.toggle('hidden',count>0);}if(e.target.matches('#scan-form textarea'))state.scanNotes=e.target.value;});
window.addEventListener('hashchange',()=>{stopCamera();if($('#dialog').open)$('#dialog').close();state.plantPhoto=null;if(routePath()==='scan'&&routeParams().get('plant'))state.scanPlantId=routeParams().get('plant');render();window.scrollTo({top:0,behavior:'instant'});});
$('#dialog').addEventListener('close',stopCamera);
initPWA({onOnlineChange:()=>render(),onUpdateAvailable:()=>{openDialog('Uma nova folha por aqui',`<p class="dialog-copy">Há uma nova versão do Ecoplant. Salve seus registros antes de atualizar.</p><button class="btn block" data-action="update-app">Atualizar aplicativo</button>`);}});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="update-app"]'))applyUpdate();});
render();
cloud.subscribeAuth(activateUser,error=>{authResolved=true;finishSplash();console.warn('Ecoplant: autenticação indisponível.',error?.code||'network');});

cloud.ready.then(result=>{if(!result.ok)finishSplash();});
